const UserEmail = module.exports;

UserEmail.exists = async function (email) {
	const uid = await user.getUidByEmail(email.toLowerCase());
	return !!uid;
};

UserEmail.available = async function (email) {
	const exists = await db.isSortedSetMember('email:uid', email.toLowerCase());
	return !exists;
};

UserEmail.getConfirmation = async function (uid) {
	const code = await db.get(`confirm:byUid:${uid}`);
	if (!code) {
		return null;
	}
	const confirmation = await db.getObject(`confirm:${code}`);
	return confirmation && parseInt(confirmation.uid, 10) === parseInt(uid, 10) ? { ...confirmation, code } : null;
};

UserEmail.isValidationPending = async function (uid, email) {
	const confirmation = await UserEmail.getConfirmation(uid);
	return !!(confirmation && confirmation.email && Number(confirmation.expires) > Date.now() &&
		(!email || confirmation.email === email.toLowerCase()));
};

UserEmail.getEmailForValidation = async function (uid) {
	const email = await user.getUserField(uid, 'email');
	if (email) {
		return email;
	}
	const confirmation = await UserEmail.getConfirmation(uid);
	return confirmation ? confirmation.email : '';
};

UserEmail.expireValidation = async function (uid) {
	const code = await db.get(`confirm:byUid:${uid}`);
	await db.delete(`confirm:byUid:${uid}`);
	if (code) {
		await db.delete(`confirm:${code}`);
	}
};

