describe('email confirm', () => {
	it('tracks pending confirmations and permits a resend after expiry', async () => {
		const uid = await User.create({ username: 'confirmationexpiry', email: 'expiry@example.com' });
		const code = await User.email.sendValidationEmail(uid, { force: true });
		const confirmation = await db.getObject(`confirm:${code}`);
		assert.strictEqual(await db.get(`confirm:byUid:${uid}`), code);
		assert(Number(confirmation.expires) > Date.now());
		assert.strictEqual(await User.email.isValidationPending(uid, 'expiry@example.com'), true);
		assert.strictEqual(await User.email.isValidationPending(uid, 'other@example.com'), false);
		await assert.rejects(User.email.sendValidationEmail(uid), /confirm-email-already-sent/);
		await db.setObjectField(`confirm:${code}`, 'expires', Date.now() - 1);
		assert.strictEqual(await User.email.isValidationPending(uid), false);
		const newCode = await User.email.sendValidationEmail(uid);
		assert.notStrictEqual(newCode, code);
		assert.strictEqual(await db.getObject(`confirm:${code}`), null);
		await User.email.expireValidation(uid);
		assert.strictEqual(await db.get(`confirm:byUid:${uid}`), null);
		assert.strictEqual(await db.getObject(`confirm:${newCode}`), null);
	});

	it('uses a pending email when the profile has none and cleans it on deletion', async () => {
		const uid = await User.create({ username: 'pendingwithoutprofile' });
		const code = await User.email.sendValidationEmail(uid, { email: 'pending@example.com' });
		assert.strictEqual(await User.email.getEmailForValidation(uid), 'pending@example.com');
		await User.deleteAccount(uid);
		assert.strictEqual(await db.get(`confirm:byUid:${uid}`), null);
		assert.strictEqual(await db.getObject(`confirm:${code}`), null);
	});

	it('should error with invalid code', (done) => {
		User.email.confirmByCode('asdasda', (err) => {
			assert.equal(err.message, '[[error:invalid-data]]');
			done();
		});
	});

	it('should confirm email of user', async () => {
		const email = 'confirm@me.com';
		const uid = await User.create({
			username: 'confirme',
			email: email,
		});

		const code = await User.email.sendValidationEmail(uid, { force: true });
		const unverified = await groups.isMember(uid, 'unverified-users');
		assert.strictEqual(unverified, true);
		await User.email.confirmByCode(code);
		const [confirmed, isVerified] = await Promise.all([
			db.getObjectField(`user:${uid}`, 'email:confirmed'),
			groups.isMember(uid, 'verified-users', uid),
		]);
		assert.strictEqual(parseInt(confirmed, 10), 1);
		assert.strictEqual(isVerified, true);
	});

	it('should confirm email of user by uid', async () => {
		const email = 'confirm2@me.com';
		const uid = await User.create({
			username: 'confirme2',
			email: email,
		});

		const unverified = await groups.isMember(uid, 'unverified-users');
		assert.strictEqual(unverified, true);
		await User.email.confirmByUid(uid);
		const [confirmed, isVerified] = await Promise.all([
			db.getObjectField(`user:${uid}`, 'email:confirmed'),
			groups.isMember(uid, 'verified-users', uid),
		]);

		return false;	// specifically to keep the menu open
	}

